Script.Source:
import sailpoint.object.*;
import sailpoint.tools.*;
import java.util.*;

// Generate a unique request ID for audit trail
String reqId = "REQ-" + System.currentTimeMillis();
workflow.put("requestId", reqId);
log.info("AccessRequestWorkflow: Initialised request " + reqId
         + " for identity: " + identityName);

// Determine if any requested entitlements are flagged as privileged
boolean needsSecApproval = false;
List privilegedKeywords = Arrays.asList("admin", "privileged", "cyberark", "pam", "root");

ProvisioningPlan plan = (ProvisioningPlan) workflow.get("plan");
if (plan != null && plan.getAccountRequests() != null) {
  for (Object reqObj : plan.getAccountRequests()) {
    ProvisioningPlan.AccountRequest req = (ProvisioningPlan.AccountRequest) reqObj;
    if (req.getAttributeRequests() != null) {
      for (Object attrObj : req.getAttributeRequests()) {
        ProvisioningPlan.AttributeRequest attr = (ProvisioningPlan.AttributeRequest) attrObj;
        String attrName = attr.getName() != null ? attr.getName().toLowerCase() : "";
        for (Object kw : privilegedKeywords) {
          if (attrName.contains((String) kw)) {
            needsSecApproval = true;
            log.info("AccessRequestWorkflow: Privileged entitlement detected: "
                     + attr.getName() + ". Security approval required.");
            break;
          }
        }
      }
    }
  }
}

workflow.put("requiresSecurityApproval", needsSecApproval);

