Script.Source:
import sailpoint.object.*;
import sailpoint.api.*;

ProvisioningPlan plan = (ProvisioningPlan) workflow.get("plan");
String identity = (String) workflow.get("identityName");

log.info("AccessRequestWorkflow: Executing provisioning plan for identity: "
         + identity + ", request: " + workflow.get("requestId"));

// Delegate to IIQ's provisioner
Provisioner provisioner = new Provisioner(context);
provisioner.execute(plan);

workflow.put("provisioningResult", "Provisioned");
log.info("AccessRequestWorkflow: Provisioning complete for request: "
         + workflow.get("requestId"));

log.info("AccessRequestWorkflow: Sending approval notification for request: "
         + workflow.get("requestId"));
// Email notification handled by IIQ email template: "Access Request Approved"

workflow.put("provisioningResult", "Rejected");
log.info("AccessRequestWorkflow: Request rejected: " + workflow.get("requestId"));
// Email notification handled by IIQ email template: "Access Request Rejected"
